const $=s=>document.querySelector(s);const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let exhibitors=[],coordinates={},state={},view='tuesday',filter='All',query='',page=0,installPrompt=null,mapHall='10',mapSelected='',mapZoom=1;
try{state=JSON.parse(localStorage.getItem(KEY)||'{}')||{}}catch{state={}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch{notify('Changes could not be saved. Check browser storage settings.');return false}}
const ACTIVITY_KEY='stuttgart-show-2026-activities-v1';
