let activities=[],tripDay='sunday',ideaCity='All',ideaCategory='All',ideaDay='All',editing=null,editorTrigger=null;
try{const stored=JSON.parse(localStorage.getItem(ACTIVITY_KEY)||'[]');if(Array.isArray(stored))activities=stored.filter(a=>a&&typeof a.id==='string'&&a.custom&&typeof a.name==='string')}catch{}
