 $('#editorTitle').textContent=e?'Edit activity':'Add activity';$('#activityName').value=e?displayName(e):suggestion?.name||'';
 $('#activityDay').innerHTML=dayOptions(e?assignedDay(e):suggestion?.day||(view==='trip'&&suggestion?.days?.includes(tripDay)?tripDay:view==='ideas'&&ideaDay!=='All'&&suggestion?.days?.includes(ideaDay)?ideaDay:suggestion?.days?.[0])||(view==='trip'?tripDay:view==='wednesday'?'wednesday':'tuesday'));
 $('#activityTime').value=e?timeOf(e):suggestion?.time||'';
