 $('#activityDetail').value=e?(s.detail??e.why??''):suggestion?[suggestion.detail,suggestion.duration?'Duration: '+suggestion.duration:'',suggestion.cost?'Price guide: '+suggestion.cost:'',suggestion.url?'Official information: '+suggestion.url:''].filter(Boolean).join('\n\n'):'';
