document.addEventListener('click',ev=>{const b=ev.target.closest('[data-suggestion]');if(b)openEditor(null,(window.LEISURE_SUGGESTIONS||[])[Number(b.dataset.suggestion)],b)});

const idOf=e=>e.custom?e.id:`${e.fair}:${e.booth.split(' · ').at(-1)}:${e.name}`;
