function displayed(){if(view==='ideas')return [];let list;if(view==='directory')list=exhibitors.filter(e=>!e.special);else if(view==='map')list=exhibitors;else if(view==='trip')list=exhibitors.filter(e=>assignedDay(e)===tripDay);else if(view==='tuesday')list=exhibitors.filter(e=>assignedDay(e)==='tuesday');else list=exhibitors.filter(e=>assignedDay(e)==='wednesday'||isSuggestion(e));if(!['directory','map'].includes(view))list=list.concat(activities.filter(a=>a.day===(view==='trip'?tripDay:view)));list=list.filter(searchMatch);return ['directory','map'].includes(view)?list.sort((a,b)=>Number(b.priority)-Number(a.priority)||a.name.localeCompare(b.name)):list.sort(sortStops)}
function card(e){if(e.custom)return activityCard(e);const s=entry(e),day=assignedDay(e),suggested=view==='wednesday'&&day!=='wednesday';const rawTime=timeOf(e);const name=escapeHTML(displayName(e));const detail=e.curated;const questions=detail?.[4]||[...e.tags.includes('Lighting')?['Can you show a sample lighting setup for plastic defects?']:[],...e.tags.includes('Cameras')?['What sensor and trigger setup fits a factory inspection line?']:[],...e.tags.includes('Robotics')?['What live demo and integration options are available?']:[]].slice(0,3);
 const tags=[...new Set(e.tags)].slice(0,5).map(t=>`<span class="tag">${escapeHTML(t)}</span>`).join('');const map=MAPS[e.fair];return `<article class="card ${e.priority?'priority':''}" data-id="${escapeHTML(idOf(e))}"><div class="card-top"><span class="time-pill">${view==='directory'?'FIND':suggested?'CATCH':rawTime?escapeHTML(rawTime):'ANY'}</span><div class="card-main"><h3>${name}</h3><div class="meta"><span>${escapeHTML(e.fair)} · ${escapeHTML(e.booth)}</span>${e.priority?'<span class="priority-label">★ Original stop</span>':''}${suggested?'<span>Missed / follow-up</span>':''}${s.visited?'<span>✓ Visited</span>':''}</div>${tags?`<div class="tagrow">${tags}</div>`:''}</div></div><div class="actions"><button class="action edit-plan" data-action="edit">Edit plan</button><button class="action locate" data-action="locate">⌖ Map</button><button class="action visit ${s.visited?'active':''}" data-action="visited" aria-pressed="${!!s.visited}">${s.visited?'✓ Visited':'○ Visited'}</button><button class="action star ${s.favorite?'active':''}" data-action="favorite" aria-pressed="${!!s.favorite}">${s.favorite?'★ Saved':'☆ Save'}</button><button class="action follow ${s.follow?'active':''}" data-action="follow" aria-pressed="${!!s.follow}">${s.follow?'✓ Follow-up':'＋ Follow-up'}</button></div><details class="details"><summary>Why visit · questions · plan · notes</summary><p>${escapeHTML(s.detail??e.why??'Official directory listing. Open the exhibitor profile to check products and fit.')}</p>${e.name.includes('CCS Europe')?'<p><strong>Booth update:</strong> the current official directory says 10E54; an earlier route used 10E58.</p>':''}${questions.length?`<strong>Ask at the booth</strong><ol>${questions.map(q=>`<li>${escapeHTML(q)}</li>`).join('')}</ol>`:''}<div class="detail-links"><a href="${escapeHTML(e.url||DIRECTORIES[e.fair])}" target="_blank" rel="noopener">Official listing ↗</a><a href="${map}" target="_blank" rel="noopener">Hall plan ↗</a></div><p class="plan-caption">${escapeHTML(DAYS[day]||'Unassigned')} · ${escapeHTML(rawTime||'Any time')}${s.location?' · '+escapeHTML(s.location):''}</p><label class="note-label">My notes<textarea data-field="note" placeholder="What did you learn? Who to contact?">${escapeHTML(s.note||'')}</textarea></label></details></article>`}
function render(){if(!exhibitors.length)return;const priorityRows=exhibitors.filter(e=>e.priority);const done=priorityRows.filter(e=>entry(e).visited).length;$('#progressCount').textContent=`${done} / 19`;$('#progressBar').style.width=`${done/19*100}%`;$('#tueCount').textContent=exhibitors.filter(e=>assignedDay(e)==='tuesday').length;$('#wedCount').textContent=exhibitors.filter(e=>assignedDay(e)==='wednesday').length;$('#dirCount').textContent='633';document.querySelectorAll('.tab').forEach(b=>{let yes=b.dataset.view===view;b.classList.toggle('active',yes);if(yes)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')});const filters=['All','Priority','Cameras','Lighting','Optics','AI','Robotics','Humanoids','Favorites'];$('#filters').innerHTML=filters.map(f=>`<button class="chip ${filter===f?'active':''}" data-filter="${f}" aria-pressed="${filter===f}">${f}</button>`).join('');$('#toolbar').hidden=view==='ideas';$('#ideaControls').hidden=view!=='ideas';$('#ideaCity').value=ideaCity;$('#ideaDate').value=ideaDay;$('#ideaCategory').innerHTML='<option value="All">All types</option>'+[...new Set((window.LEISURE_SUGGESTIONS||[]).map(s=>s.category).filter(Boolean))].sort().map(c=>'<option value="'+escapeHTML(c)+'" '+(c===ideaCategory?'selected':'')+'>'+escapeHTML(c)+'</option>').join('');$('#list').hidden=view==='ideas';$('#tripControls').hidden=view!=='trip';$('#tripDay').value=tripDay;renderLeisure();const headings={ideas:['City ideas','Fun things to do in Munich and Stuttgart, ready to add to your plan.'],trip:[DAYS[tripDay]||'Unassigned activities', 'Your activities for 4–8 October. Exhibition plans remain in their own tabs.'],tuesday:['Tuesday · 6 October','Your route, starting in VISION Halls 10 and 8, then Motek Hall 6.'],wednesday:['Wednesday · 7 October','Assigned stops plus unfinished Tuesday visits and saved follow-ups.'],directory:['All exhibitors','Search the dated official snapshots, then add any company to your plan.'],map:['Find a booth','Tap an exhibitor below to center its location, then drag or zoom the map.']};const list=displayed(),count=view==='ideas'?ideaRows().length:list.length;$('#viewHeading').innerHTML=`<div><h2>${headings[view][0]}</h2><p>${headings[view][1]}</p></div><span class="count">${count} ${view==='ideas'?'idea':'result'}${count===1?'':'s'}</span>`;$('#suggestions').hidden=view!=='wednesday';if(view==='wednesday'){const missed=exhibitors.filter(e=>assignedDay(e)==='tuesday'&&!entry(e).visited).length,follow=exhibitors.filter(e=>entry(e).follow&&!entry(e).visited).length;$('#suggestions').innerHTML=`<strong>Catch-up queue</strong><p>${missed} Tuesday stop${missed===1?'':'s'} still unvisited · ${follow} follow-up${follow===1?'':'s'} saved. Assign a time to make a Wednesday stop firm.</p>`}$('#mapPanel').hidden=view!=='map';if(view==='map')renderMap();let visible=['directory','map'].includes(view)?list.slice(0,(page+1)*60):list;$('#list').innerHTML=visible.length?visible.map(card).join(''):'<div class="empty">No matching stops. Try another search or category.</div>';$('#moreWrap').hidden=!['directory','map'].includes(view)||visible.length>=list.length;}
function plottedPosition(e,hall=mapHall){if(e.fair==='Motek')return hall==='6'?[.535,.60]:null;const booths=[...e.booth.matchAll(/\b(?:8|10)[A-Z]\d{2}(?:\.\d+)?\b/g)].map(m=>m[0]);const booth=booths.find(b=>b.startsWith(hall)&&coordinates[b]);return booth?coordinates[booth]:null}
