function centerMap(position){const stage=$('#mapStage'),layer=$('#mapLayer');if(!stage||!layer)return;const x=position?.[0]??.5,y=position?.[1]??.5;stage.scrollTo({left:Math.max(0,x*layer.offsetWidth-stage.clientWidth/2),top:Math.max(0,y*layer.offsetHeight-stage.clientHeight/2),behavior:'smooth'})}
function renderMap(){const hall=mapHall,selected=exhibitors.find(e=>idOf(e)===mapSelected);const plan=hall==='6'?'venue-overview.webp':`hall-${hall}.webp`;const isMotek=hall==='6';const pos=selected?plottedPosition(selected,hall):null;$('#mapTitle').textContent=isMotek?'Motek · Hall 6':`VISION · Hall ${hall}`;$('#mapCaption').textContent=isMotek?'Hall location only: a current booth-level Hall 6 plan is not published.':'Official hall plan from June 2026. Pins are based on booth labels; check signs on site.';$('#mapHalls').innerHTML=['10','8','6'].map(h=>`<button type="button" data-hall="${h}" class="${hall===h?'active':''}" aria-pressed="${hall===h}">Hall ${h}</button>`).join('');const stage=$('#mapStage'),layer=$('#mapLayer'),ratio=1191/842;const width=Math.max(stage.clientWidth||330,stage.clientHeight*ratio)*mapZoom;layer.style.width=`${width}px`;layer.style.height=`${width/ratio}px`;let pins=[];if(isMotek){pins=[{e:selected?.fair==='Motek'?selected:null,pos:[.535,.60],selected:true}]}else{const shown=query||filter!=='All'?displayed().filter(e=>e.fair==='VISION').slice(0,80):exhibitors.filter(e=>e.priority&&e.fair==='VISION');pins=shown.filter(e=>plottedPosition(e,hall)).map(e=>({e,pos:plottedPosition(e,hall),selected:idOf(e)===mapSelected}));if(selected?.fair==='VISION'&&pos&&!pins.some(p=>p.selected))pins.push({e:selected,pos,selected:true})}layer.innerHTML=`<img src="${plan}" alt="${isMotek?'Messe Stuttgart venue overview':'Official VISION Hall '+hall+' floor plan'}" draggable="false">`+pins.map(p=>`<button type="button" class="map-pin ${p.selected?'selected':''}" data-pin="${p.e?escapeHTML(idOf(p.e)):''}" style="left:${p.pos[0]*100}%;top:${p.pos[1]*100}%" aria-label="${p.e?'Locate '+escapeHTML(p.e.name):'Hall 6'}"></button>`).join('');let note;if(!selected)note='Choose an exhibitor below to center its location.';else if(isMotek&&selected.fair==='Motek')note=`<strong>${escapeHTML(selected.name)}</strong><span>Hall 6 · ${escapeHTML(selected.booth.split(' · ').at(-1))}. Exact booth position is not available on the published 2026 plan.</span>`;else if(pos)note=`<strong>${escapeHTML(selected.name)}</strong><span>Hall ${hall} · ${escapeHTML(selected.booth.split(' · ').at(-1))}. Pin is on the official hall plan.</span>`;else note=`<strong>${escapeHTML(selected.name)}</strong><span>The directory lists ${escapeHTML(selected.booth)}. This booth is not plotted on the published plan; use the official listing or signs on site.</span>`;$('#mapSelection').innerHTML=note;requestAnimationFrame(()=>centerMap(pos||[.5,.5]))}
document.addEventListener('click',ev=>{const hall=ev.target.closest('[data-hall]');if(hall){mapHall=hall.dataset.hall;mapSelected='';mapZoom=1;renderMap();return}const zoom=ev.target.closest('[data-zoom]');if(zoom){mapZoom=Math.min(3.4,Math.max(1,mapZoom*(zoom.dataset.zoom==='in'?1.4:1/1.4)));renderMap();return}const pin=ev.target.closest('[data-pin]');if(pin){if(pin.dataset.pin){mapSelected=pin.dataset.pin;renderMap()}return}const tab=ev.target.closest('[data-view]');if(tab){view=tab.dataset.view;page=0;render();return}const chip=ev.target.closest('[data-filter]');if(chip){filter=chip.dataset.filter;page=0;render();return}const button=ev.target.closest('[data-action]');if(button){const e=[...exhibitors,...activities].find(x=>idOf(x)===button.closest('[data-id]').dataset.id);const key=button.dataset.action;if(key==='edit'){openEditor(e,null,button);return}if(key==='locate'){locate(e);return}mutate(e,{[key]:!entry(e)[key]})}});
document.addEventListener('change',ev=>{const field=ev.target.dataset.field;if(!field||field==='note')return;const e=exhibitors.find(x=>idOf(x)===ev.target.closest('[data-id]').dataset.id);mutate(e,{[field]:ev.target.value})});
document.addEventListener('input',ev=>{if(ev.target.dataset.field==='note'){const e=[...exhibitors,...activities].find(x=>idOf(x)===ev.target.closest('[data-id]').dataset.id);if(e.custom){activities=activities.map(a=>a.id===e.id?{...a,note:ev.target.value}:a);saveActivities()}else{state[idOf(e)]={...entry(e),note:ev.target.value};save()}}});
$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();page=0;render()});$('#moreBtn').addEventListener('click',()=>{page++;render()});
function connection(){ $('#connectionDot').classList.toggle('offline',!navigator.onLine);$('#connectionDot').title=navigator.onLine?'Online':'Offline — saved app data is available'}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('#installBtn').hidden=false});$('#installBtn').addEventListener('click',async()=>{if(installPrompt){installPrompt.prompt();await installPrompt.userChoice;installPrompt=null;$('#installBtn').hidden=true}});
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
Promise.all(['./exhibitors.json','./booth-coordinates.json'].map(u=>fetch(u).then(r=>{if(!r.ok)throw Error('Snapshot unavailable');return r.json()}))).then(([rows,positions])=>{coordinates=positions;setupData(rows)}).catch(()=>{$('#list').innerHTML='<div class="empty">The exhibitor snapshot could not load. Connect once and reload to save it for offline use.</div>'});
